local util = require("util")

-- The turret head: a purpose-drawn 64-direction emitter sheet, generated by
-- graphics/_generator/melta_head.py. Geometry is measured from the rocket turret
-- head it replaces, so it drops into the same rig without touching the base:
--
--   frame 160x164, 64 directions, 1 frame each, line_length 1
--   3 files with 22 / 22 / 20 rows, layer shift by_pixel(0, -8.5), scale 0.5
--
-- The base/hull stays the rocket turret's own art exactly as it shipped.
local HEAD =
{
  filenames =
  {
    "__lilys-melta__/graphics/entity/melta-turret/melta-turret-head-1.png",
    "__lilys-melta__/graphics/entity/melta-turret/melta-turret-head-2.png",
    "__lilys-melta__/graphics/entity/melta-turret/melta-turret-head-3.png"
  },
  lines_per_file = 22,
  line_length = 1,
  width = 160,
  height = 164,
  frame_count = 1,
  direction_count = 64,
  slice = 1,
  shift = util.by_pixel(0, -8.5),
  scale = 0.5,
  priority = "medium"
}

local function head_layers()
  return {layers = {table.deepcopy(HEAD)}}
end

return
{
  attacking_animation = head_layers(),
  prepared_animation = head_layers(),
  preparing_animation = head_layers(),
  ending_attack_animation = head_layers(),
  -- no fold/unfold: the emitter is always deployed, which keeps the head a single
  -- sheet instead of an 18-frame deploy strip nothing else would reuse
  folded_animation = head_layers(),
  folding_animation = head_layers()
}
